import re


def calc(expr: str) -> int | str:
    tokens = re.findall(r"[0-9]+|[+\-*/%^()]", expr)
    tokens.append("")
    idx = 0

    def parse_int(s: str) -> int:
        if len(s) <= 4000:
            return int(s)
        res = 0
        for i in range(0, len(s), 4000):
            chunk = s[i : i + 4000]
            res = res * (10 ** len(chunk)) + int(chunk)
        return res

    def parse_expr() -> int:
        nonlocal idx
        val = parse_term()
        while True:
            tok = tokens[idx]
            if tok == "+":
                idx += 1
                val += parse_term()
            elif tok == "-":
                idx += 1
                val -= parse_term()
            else:
                return val

    def parse_term() -> int:
        nonlocal idx
        val = parse_unary()
        while True:
            tok = tokens[idx]
            if tok == "*":
                idx += 1
                val *= parse_unary()
            elif tok == "/":
                idx += 1
                rhs = parse_unary()
                if rhs == 0:
                    raise ZeroDivisionError
                q = abs(val) // abs(rhs)
                val = -q if (val < 0) ^ (rhs < 0) else q
            elif tok == "%":
                idx += 1
                rhs = parse_unary()
                if rhs == 0:
                    raise ZeroDivisionError
                r = abs(val) % abs(rhs)
                val = -r if val < 0 else r
            else:
                return val

    def parse_primary() -> int:
        nonlocal idx
        tok = tokens[idx]
        if tok == "(":
            idx += 1
            val = parse_expr()
            idx += 1
            return val
        idx += 1
        return parse_int(tok)

    def parse_unary() -> int:
        nonlocal idx
        chain: list[tuple[bool, int]] = []
        while True:
            neg = False
            while tokens[idx] == "-":
                neg = not neg
                idx += 1
            base = parse_primary()
            chain.append((neg, base))
            if tokens[idx] == "^":
                idx += 1
            else:
                break

        neg, val = chain.pop()
        if neg:
            val = -val
        while chain:
            neg, base = chain.pop()
            if val < 0:
                raise ZeroDivisionError
            if base == 0:
                val = 1 if val == 0 else 0
            elif base == 1:
                val = 1
            elif base == -1:
                val = -1 if (val & 1) else 1
            else:
                val = base ** val
            if neg:
                val = -val
        return val

    try:
        return parse_expr()
    except ZeroDivisionError:
        return "error"
